#ifdef __cplusplus extern "C" { #endif
#include "bsp_mcu_device_pn_cfg.h" #include "bsp_mcu_device_cfg.h" #include "../../../ra/fsp/src/bsp/mcu/ra2l2/bsp_mcu_info.h" #include "../../../ra/fsp/src/bsp/mcu/ra2l2/bsp_override.h" #include "bsp_clock_cfg.h" #define BSP_MCU_GROUP_RA2L2 (1) #define BSP_LOCO_HZ (32768) #define BSP_MOCO_HZ (8000000) #define BSP_SUB_CLOCK_HZ (32768) #if BSP_CFG_HOCO_FREQUENCY == 0 #define BSP_HOCO_HZ (24000000) #elif BSP_CFG_HOCO_FREQUENCY == 2 #define BSP_HOCO_HZ (32000000) #elif BSP_CFG_HOCO_FREQUENCY == 4 #define BSP_HOCO_HZ (48000000) #elif BSP_CFG_HOCO_FREQUENCY == 5 #define BSP_HOCO_HZ (64000000) #else #error "Invalid HOCO frequency chosen (BSP_CFG_HOCO_FREQUENCY) in bsp_clock_cfg.h" #endif
#define BSP_CORTEX_VECTOR_TABLE_ENTRIES (16U) #define BSP_VECTOR_TABLE_MAX_ENTRIES (48U) #define BSP_CFG_INLINE_IRQ_FUNCTIONS (${config.bsp.fsp.inline_irq_functions})
#define OFS_SEQ1 0xA001A001 | (${config.bsp.fsp.OFS0.iwdt_start_mode}) | (${config.bsp.fsp.OFS0.iwdt_timeout}) #define OFS_SEQ2 (${config.bsp.fsp.OFS0.iwdt_divisor}) | (${config.bsp.fsp.OFS0.iwdt_window_end}) | (${config.bsp.fsp.OFS0.iwdt_window_start}) #define OFS_SEQ3 (${config.bsp.fsp.OFS0.iwdt_reset_interrupt}) | (${config.bsp.fsp.OFS0.iwdt_stop_control}) | (${config.bsp.fsp.OFS0.wdt_start_mode}) #define OFS_SEQ4 (${config.bsp.fsp.OFS0.wdt_timeout}) |(${config.bsp.fsp.OFS0.wdt_divisor}) | (${config.bsp.fsp.OFS0.wdt_window_end}) | (${config.bsp.fsp.OFS0.wdt_window_start}) #define OFS_SEQ5 (${config.bsp.fsp.OFS0.wdt_reset_interrupt}) | (${config.bsp.fsp.OFS0.wdt_stop_control}) #define BSP_CFG_USE_LOW_VOLTAGE_MODE (${config.bsp.low_voltage_mode}) #define BSP_CFG_ROM_REG_OFS0 (OFS_SEQ1 | OFS_SEQ2 | OFS_SEQ3 | OFS_SEQ4 | OFS_SEQ5) #define BSP_CFG_ROM_REG_OFS1_ICSATS (${config.bsp.fsp.OFS1.internal_clock_supply}) #define BSP_CFG_ROM_REG_OFS1 (0x7FFFFEC3 | (${config.bsp.fsp.OFS1.voltage_detection0.start}) | (${config.bsp.fsp.OFS1.voltage_detection0_level}) | (${config.bsp.fsp.OFS1.hoco_osc}) | (BSP_CFG_ROM_REG_OFS1_ICSATS)) #define BSP_CFG_ROM_REG_MPU_PC0_ENABLE (${config.bsp.fsp.mpu_pc0_enable}) #define BSP_CFG_ROM_REG_MPU_PC0_START (${config.bsp.fsp.mpu_pc0_start}) #define BSP_CFG_ROM_REG_MPU_PC0_END (${config.bsp.fsp.mpu_pc0_end}) #define BSP_CFG_ROM_REG_MPU_PC1_ENABLE (${config.bsp.fsp.mpu_pc1_enable}) #define BSP_CFG_ROM_REG_MPU_PC1_START (${config.bsp.fsp.mpu_pc1_start}) #define BSP_CFG_ROM_REG_MPU_PC1_END (${config.bsp.fsp.mpu_pc1_end}) #define BSP_CFG_ROM_REG_MPU_REGION0_ENABLE (${config.bsp.fsp.mpu_reg0_enable}) #define BSP_CFG_ROM_REG_MPU_REGION0_START (${config.bsp.fsp.mpu_reg0_start}) #define BSP_CFG_ROM_REG_MPU_REGION0_END (${config.bsp.fsp.mpu_reg0_end}) #define BSP_CFG_ROM_REG_MPU_REGION1_ENABLE (${config.bsp.fsp.mpu_reg1_enable}) #define BSP_CFG_ROM_REG_MPU_REGION1_START (${config.bsp.fsp.mpu_reg1_start}) #define BSP_CFG_ROM_REG_MPU_REGION1_END (${config.bsp.fsp.mpu_reg1_end}) #define BSP_CFG_ROM_REG_MPU_REGION2_ENABLE (${config.bsp.fsp.mpu_reg2_enable}) #define BSP_CFG_ROM_REG_MPU_REGION2_START (${config.bsp.fsp.mpu_reg2_start}) #define BSP_CFG_ROM_REG_MPU_REGION2_END (${config.bsp.fsp.mpu_reg2_end}) #define BSP_CFG_ROM_REG_MPU_REGION3_ENABLE (${config.bsp.fsp.mpu_reg3_enable}) #define BSP_CFG_ROM_REG_MPU_REGION3_START (${config.bsp.fsp.mpu_reg3_start}) #define BSP_CFG_ROM_REG_MPU_REGION3_END (${config.bsp.fsp.mpu_reg3_end}) #ifndef BSP_CLOCK_CFG_MAIN_OSC_WAIT #define BSP_CLOCK_CFG_MAIN_OSC_WAIT (${config.bsp.common.main_osc_wait}) #endif
/* Used to create IELS values for the interrupt initialization table g_interrupt_event_link_select. */ #define BSP_PRV_IELS_ENUM(vector) (ICU_ ## vector) /* ID Code Note: To lock and disable the debug interface define BSP_ID_CODE_LOCKED in compiler settings. WARNING: This will disable debug access to the part. However, ALeRASE command will be accepted, which will clear (reset) the ID code. After clearing ID code, debug access will be enabled. Please read the HWM for full details of the clearing process. */ #if defined(BSP_ID_CODE_LOCKED) #define BSP_CFG_ID_CODE_LONG_1 (0x00000000) #define BSP_CFG_ID_CODE_LONG_2 (0x00000000) #define BSP_CFG_ID_CODE_LONG_3 (0x00000000) #define BSP_CFG_ID_CODE_LONG_4 (0x00000000) #else /* ID CODE: ${config.bsp.common.id_fixed} */ #define BSP_CFG_ID_CODE_LONG_1 (0x${config.bsp.common.id1}) #define BSP_CFG_ID_CODE_LONG_2 (0x${config.bsp.common.id2}) #define BSP_CFG_ID_CODE_LONG_3 (0x${config.bsp.common.id3}) #define BSP_CFG_ID_CODE_LONG_4 (0x${config.bsp.common.id4}) #endif
#ifdef __cplusplus } #endif
